WITH metrics AS (SELECT *, LAG(units, 1) OVER (PARTITION BY store_id ORDER BY units ASC, id ASC) AS prev_units, AVG(revenue) OVER (PARTITION BY store_id ORDER BY revenue ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS revenue_avg_3, LAG(units, 1) OVER (ORDER BY revenue ASC, id ASC) AS prev_units_2, RANK() OVER w_part AS units_rank FROM store_sales WINDOW w_part AS (PARTITION BY product_id ORDER BY units DESC NULLS FIRST)) SELECT id, store_id, product_id, revenue, prev_units, revenue_avg_3, prev_units_2, units_rank FROM metrics
